export interface DlpJobTriggerConfig {
  /** Contains a configuration to make API calls on a repeating basis. See https://docs.cloud.google.com/sensitive-data-protection/docs/concepts-job-triggers to learn more. */
  jobTrigger?: DlpJobTrigger_JobTrigger | Computed<DlpJobTrigger_JobTrigger>;
  /** Deprecated. This field has no effect. */
  locationId?: string | Computed<string>;
  /** The trigger id can contain uppercase and lowercase letters, numbers, and hyphens; that is, it must match the regular expression: `[a-zA-Z\d-_]+`. The maximum length is 100 characters. Can be empty to allow the system to generate one. */
  triggerId?: string | Computed<string>;
}

export interface DlpJobTriggerAttrs {
  /** Output only. The creation timestamp of a triggeredJob. */
  createTime: string;
  /** User provided description (max 256 chars) */
  description: string;
  /** Display name (max 100 chars) */
  displayName: string;
  /** Output only. A stream of errors encountered when the trigger was activated. Repeated errors may result in the JobTrigger automatically being paused. Will return the last 100 errors. Whenever the JobTrigger is modified this list will be cleared. */
  errors: DlpJobTrigger_Errors[];
  /** Controls what and how to inspect for findings. */
  inspectJob: DlpJobTrigger_InspectJob;
  /** Contains a configuration to make API calls on a repeating basis. See https://docs.cloud.google.com/sensitive-data-protection/docs/concepts-job-triggers to learn more. */
  jobTrigger: DlpJobTrigger_JobTrigger;
  /** Output only. The timestamp of the last time this trigger executed. */
  lastRunTime: string;
  /** Deprecated. This field has no effect. */
  locationId: string;
  /** Output only. Unique resource name for the triggeredJob, assigned by the service when the triggeredJob is created, for example `projects/dlp-test-project/jobTriggers/53234423`. */
  name: string;
  /** Required. A status for this trigger. */
  status: string;
  /** The trigger id can contain uppercase and lowercase letters, numbers, and hyphens; that is, it must match the regular expression: `[a-zA-Z\d-_]+`. The maximum length is 100 characters. Can be empty to allow the system to generate one. */
  triggerId: string;
  /** A list of triggers which will be OR'ed together. Only one in the list needs to trigger for a job to be started. The list may contain only a single Schedule trigger and must have at least one object. */
  triggers: DlpJobTrigger_JobTrigger_Triggers[];
  /** Output only. The last update timestamp of a triggeredJob. */
  updateTime: string;
}

